import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-01-08 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-01-08 :: Ceph Orchestration Meeting","date":"2020-01-08T00:00:00.000Z","updated":"2020-01-11T00:00:00.000Z","tags":["Ceph","会议纪要","分布式存储","OSD","Rook"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-08_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-01-08_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-01-08_-_-_Ceph_Orchestration_Meeting.md"};function r(n,a,s,h,d,u){return l(),t("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-2020年1月8日" tabindex="-1">会议时间：2020年1月8日 <a class="header-anchor" href="#会议时间-2020年1月8日" aria-label="Permalink to &quot;会议时间：2020年1月8日&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Self-ADM 功能进展</strong></p><ul><li>Sage 在将 self-adm 集成到 totality 方面取得了进展。</li><li>Paul Kastner 为 self-edm 监控方面做了大量工作，效果显著。</li></ul></li><li><p><strong>OSD 移除流程简化</strong></p><ul><li>讨论了简化 OSD 移除流程的可能性，Sage 认为应保持 self-adm 代码简单，并由 dashboard 等其他组件实现移除功能。</li><li>目前 Rook 中移除 OSD 的步骤较为繁琐，有七个步骤，但简化空间有限。</li></ul></li><li><p><strong>OSD 替换流程</strong></p><ul><li>讨论了 OSD 替换的复杂性，包括磁盘替换前后的处理步骤。</li><li>提出了两阶段操作的建议：首先标记 OSD 为销毁状态，然后在 Ceph 中重新创建 OSD。</li></ul></li><li><p><strong>Python 客户端代码生成</strong></p><ul><li>讨论了 Python 客户端代码生成的问题，特别是设置验证的手动更新。</li><li>Sebastian 表示需要找到时间来处理这个问题。</li></ul></li><li><p><strong>Rook 安全审查</strong></p><ul><li>讨论了 Rook 的安全审查结果，主要问题是敏感信息的日志记录，已有一个 PR 处理该问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>需要进一步讨论 OSD 移除和替换流程的简化方案。</li><li>Python 客户端代码生成问题需要尽快解决。</li><li>持续关注和改进 Rook 的安全问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>下周与 Sage 讨论 OSD 移除和替换流程的具体实现方案。</li><li>Sebastian 将尽快处理 Python 客户端代码生成问题。</li><li>继续跟进 Rook 的安全审查问题，并实施必要的改进措施。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>Rook 1.2 版本已发布，计划进行第一次补丁发布。</li><li>需要确保端口设置在 1 到 65000 范围内，以加强 CRD 验证。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，下次会议将在下周进行。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的具体技术细节和代码实现需要进一步的技术文档和讨论支持。</li></ul>',15)])])}const p=e(o,[["render",r]]);export{c as __pageData,p as default};
